/* 학습 해설
 * Lockref put_return·새값 또는-1과 CAS 없는 구성
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * CAS CODE는 old.count<=0이면-1을 반환하고 양수이면 new.count를 하나 낮춥니다. 성공하면 new.count를 반환하여 count1에서0으로 내려갈 수도 있습니다. macro이후는 바로-1이며 spinlock fallback이 없습니다. CAS가 선택되지 않은 구성,lock이 held인 snapshot,100회 실패도-1로 종료될 수 있어 count가dead였다는 단일 의미로 해석할 수 없습니다.
 * 반환>=0에서만 실제 감소 결과로 처리합니다. -1이면 상위의 적절한 fallback 프로토콜을 사용하고 감소가 있었다고 가정하지 않습니다.0반환이 객체 메모리를 자동 해제한다는 뜻도 아닙니다.
 */
int lockref_put_return(struct lockref *lockref)
{
	CMPXCHG_LOOP(
		new.count--;
		if (old.count <= 0)
			return -1;
	,
		return new.count;
	);
	return -1;
}
EXPORT_SYMBOL(lockref_put_return);

