/* 학습 해설
 * Lockref put_or_lock·마지막 참조에서 잠금 인계
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * count>1이면 감소 성공1을 반환하고 잠금을 보유하지 않습니다. count<=1이면 CAS loop에서 break한 뒤 spin_lock을 잡습니다. 잠금 아래에도 count<=1이면 감소 없이0을 반환하면서 lock을 계속 보유합니다. 경쟁으로 count가 커졌으면 감소하고 unlock한 뒤1입니다.0반환 경로는 호출자가 마지막 참조의 상태 처리를 잠금 아래 이어가는 인계입니다.
 * 반환0이면 count를 무조건0으로 간주하지 말고 잠금 아래 실제 상태와 마지막 처리 규약을 확인합니다. 이후 대응 unlock의 책임을 수행합니다. 반환1이면 이미 해제된 잠금을 다시 unlock하지 않습니다.
 */
int lockref_put_or_lock(struct lockref *lockref)
{
	CMPXCHG_LOOP(
		new.count--;
		if (old.count <= 1)
			break;
	,
		return 1;
	);

	spin_lock(&lockref->lock);
	if (lockref->count <= 1)
		return 0;
	lockref->count--;
	spin_unlock(&lockref->lock);
	return 1;
}
EXPORT_SYMBOL(lockref_put_or_lock);

