/* 학습 해설
 * Lockref mark_dead와 is_dead·음수 sentinel와 잠금 전제
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * mark_dead는 assert_spin_locked로 잠금 보유 전제를 확인하고 count=-128로 표시합니다. __lockref_is_dead는 count<0의 bool을 반환하며 헤더는 신뢰할 결과를 위해 spinlock 아래 호출해야 한다고 설명합니다. dead 표시가 객체 메모리를 직접 free하지는 않습니다. 음수 sentinel와 일반 참조 수0은 다른 상태입니다.
 * 정해진 수명 종료 프로토콜에서 잠금 아래 dead를 표시하고 조회합니다. dead 뒤의 count 증가 조건을 각 API에서 확인합니다. 잠금 없이 조회한 숫자를 근거로 임의 객체 접근의 안전성을 판단하지 않습니다.
 */
void lockref_mark_dead(struct lockref *lockref)
{
	assert_spin_locked(&lockref->lock);
	lockref->count = -128;
}
EXPORT_SYMBOL(lockref_mark_dead);

