/* 학습 해설
 * Lockref get_not_dead·0참조와 dead의 다른 상태
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * get_not_dead는 old.count<0일 때만 실패하고0은1로 증가시킬 수 있습니다. fallback도 잠금 아래 count>=0을 허용합니다. get_not_zero가0도 거절하는 것과 차이입니다. 이 API가 해제된 메모리를 부활시키는 것은 아니며 객체가 아직 존재하고 dead 표시 및 마지막 처리와 양립하는 상위 규약 안에서만 의미가 있습니다.
 * 0과 dead를 구분해야 하는 사용 프로토콜에서 선택합니다. 이미 해제된 주소에는 적용하지 않습니다. 반환1로 새 참조를 얻었을 때 대응 감소와 수명 관리 규칙을 지킵니다.
 */
int lockref_get_not_dead(struct lockref *lockref)
{
	int retval;

	CMPXCHG_LOOP(
		new.count++;
		if (old.count < 0)
			return 0;
	,
		return 1;
	);

	spin_lock(&lockref->lock);
	retval = 0;
	if (lockref->count >= 0) {
		lockref->count++;
		retval = 1;
	}
	spin_unlock(&lockref->lock);
	return retval;
}
EXPORT_SYMBOL(lockref_get_not_dead);

