/* 학습 해설
 * Local lock 타입·일반 debug 구성과 빈 구조체
 * CPU별자료를보호하는문맥제어와RT잠금의다른구현을실제소스에서읽어사용조건과동작원리를배웁니다.
 * PREEMPT_RT가아니면local_lock_t는구조체입니다. DEBUG_LOCK_ALLOC이있을때dep_map과owner를포함하고없으면GNU C의빈구조체가됩니다. debug없는실행에서 acquire/release/debug_init은빈함수입니다. 정상보호는 preempt 나 IRQ 문맥제어에서오며debug필드가없다고문맥 보호까지없어지는것은아닙니다.
 * 자료크기와실행보호를구분합니다. kernel의GNU C빌드문맥을확인하고빈구조체를임의ISO C환경에서동일하게지원한다고가정하지않습니다. lockdep필드의존코드를 CONFIG와함께읽습니다.
 */
static inline void local_lock_acquire(local_lock_t *l)
{
	lock_map_acquire(&l->dep_map);
	DEBUG_LOCKS_WARN_ON(l->owner);
	l->owner = current;
}

static inline void local_lock_release(local_lock_t *l)
{
	DEBUG_LOCKS_WARN_ON(l->owner != current);
	l->owner = NULL;
	lock_map_release(&l->dep_map);
}

static inline void local_lock_debug_init(local_lock_t *l)
{
	l->owner = NULL;
}
#else /* CONFIG_DEBUG_LOCK_ALLOC */
# define LOCAL_LOCK_DEBUG_INIT(lockname)
static inline void local_lock_acquire(local_lock_t *l) { }
static inline void local_lock_release(local_lock_t *l) { }
static inline void local_lock_debug_init(local_lock_t *l) { }
#endif /* !CONFIG_DEBUG_LOCK_ALLOC */

#define INIT_LOCAL_LOCK(lockname)	{ LOCAL_LOCK_DEBUG_INIT(lockname) }

