/* 학습 해설
 * PerCPU rwsem 표현·읽기 카운터와 쓰기 차단 분리
 * 읽기많은자료의CPU별카운터와RCU전환,쓰기배제및대기열을실제원문에서연결하여확장성기술의원리를배웁니다.
 * 구조체는 RCU-sync rss,CPU별 unsigned read_count,단일 writer의rcuwait,reader/writer 대기열waiters,atomic block,조건부lockdep map을가집니다. read_count는읽기보유의합을,block은새읽기차단과 writer 간배제를,RCU-sync는빠른 읽기경로의사용여부를관리합니다. 각각다른역할이므로block0만으로즉시 fastpath가복귀했다고판단하지않습니다.
 * 읽기가많고쓰기드문자료의보호조건을검토합니다. 객체와per-CPU 배열의수명을유지하고읽기/쓰기API를정상 짝으로사용합니다. block과 rss와 count를한숫자잠금 상태로합쳐설명하지않습니다.
 */
struct percpu_rw_semaphore {
	struct rcu_sync		rss;
	unsigned int __percpu	*read_count;
	struct rcuwait		writer;
	wait_queue_head_t	waiters;
	atomic_t		block;
#ifdef CONFIG_DEBUG_LOCK_ALLOC
	struct lockdep_map	dep_map;
#endif
};

#ifdef CONFIG_DEBUG_LOCK_ALLOC
#define __PERCPU_RWSEM_DEP_MAP_INIT(lockname)	.dep_map = { .name = #lockname },
#else
#define __PERCPU_RWSEM_DEP_MAP_INIT(lockname)
#endif

#define __DEFINE_PERCPU_RWSEM(name, is_static)				\
static DEFINE_PER_CPU(unsigned int, __percpu_rwsem_rc_##name);		\
is_static struct percpu_rw_semaphore name = {				\
	.rss = __RCU_SYNC_INITIALIZER(name.rss),			\
	.read_count = &__percpu_rwsem_rc_##name,			\
	.writer = __RCUWAIT_INITIALIZER(name.writer),			\
	.waiters = __WAIT_QUEUE_HEAD_INITIALIZER(name.waiters),		\
	.block = ATOMIC_INIT(0),					\
	__PERCPU_RWSEM_DEP_MAP_INIT(name)				\

