/* 학습 해설
 * PerCPU waiter·대기열 등록과 private NULL handshake
 * 읽기많은자료의CPU별카운터와RCU전환,쓰기배제및대기열을실제원문에서연결하여확장성기술의원리를배웁니다.
 * waitersspinlockIRQ구간에서trylock을다시시도합니다. 실패하면EXCLUSIVE와 reader의CUSTOM표시를넣고tail에등록합니다. 잠금해제 뒤 TASK_UNINTERRUPTIBLE로상태를설정하고private를 acquire로조회합니다. wakecallback이보유를획득한뒤privateNULL을 release로공개하면 loop를끝내 TASK_RUNNING으로복구합니다. 등록과wake의직렬화가놓친깨움을막습니다.
 * 대기열tail순서,task 상태,private의 release/acquire인계를함께읽습니다. NULL은단순포인터없음이아니라이프로토콜의완료표시입니다. stackwaitentry의수명을 loop와 callback 조건에맞춰보호합니다.
 */
static void percpu_rwsem_wait(struct percpu_rw_semaphore *sem, bool reader)
{
	DEFINE_WAIT_FUNC(wq_entry, percpu_rwsem_wake_function);
	bool wait;

	spin_lock_irq(&sem->waiters.lock);
	/*
	 * Serialize against the wakeup in percpu_up_write(), if we fail
	 * the trylock, the wakeup must see us on the list.
	 */
	wait = !__percpu_rwsem_trylock(sem, reader);
	if (wait) {
		wq_entry.flags |= WQ_FLAG_EXCLUSIVE | reader * WQ_FLAG_CUSTOM;
		__add_wait_queue_entry_tail(&sem->waiters, &wq_entry);
	}
	spin_unlock_irq(&sem->waiters.lock);

	while (wait) {
		set_current_state(TASK_UNINTERRUPTIBLE);
		if (!smp_load_acquire(&wq_entry.private))
			break;
		schedule();
	}
	__set_current_state(TASK_RUNNING);
}

